/**
 * Default social share card, generated by the `[locale]/opengraph-image` route in the
 * True Aim brand style (page tint, structured grid, symbol, Inter Tight headline).
 *
 * Pages that declare their own `openGraph` in metadata lose the inherited image, because
 * Next.js does not deep-merge `openGraph` across route segments. Such pages should spread
 * these into their metadata so links still render a branded card on LinkedIn/Slack. Pages
 * that ship their own `opengraph-image` file (the product pages) don't need this.
 */
export const DEFAULT_OG_IMAGE = "https://trueaim.ai/opengraph-image";

export const defaultOgImages = [
  {
    url: DEFAULT_OG_IMAGE,
    width: 1200,
    height: 630,
    alt: "True Aim. Automate insurance claim decisions. Auditable by design.",
  },
];
